import{z as o,x as B,o as r,c as m,q as A,j as n,D as t,d as e,s as i,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const U=JSON.parse('{"title":"混合匹配与套刻拼接","description":"","frontmatter":{"title":"混合匹配与套刻拼接","date":"2026-09-27T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/mix-and-match-overlay.md","filePath":"litho/mix-and-match-overlay.md","lastUpdated":1791063341000}'),d={name:"litho/mix-and-match-overlay.md"};function h(p,a,D,c,M,V){const l=B("Mermaid");return r(),m("div",null,[a[2]||(a[2]=A('<h1 id="混合匹配与套刻拼接" tabindex="-1">混合匹配与套刻拼接 <a class="header-anchor" href="#混合匹配与套刻拼接" aria-label="Permalink to &quot;混合匹配与套刻拼接&quot;">​</a></h1><div class="epigraph"><p>同一层图形，关键区域交给 EUV、其余交给 DUV——混合匹配省的是钱，考的是两台机器之间的套刻。</p><footer>—— 据 ASML Mix-and-Match 工艺方案； imec 混合光刻路线图评估</footer></div><p><a href="/litho/reticle-field-limit">掩模版与场域极限</a>讲一台机器内的疆界，本课讲两台机器接力：<strong>混合匹配（mix-and-match, MAM）</strong>——同一晶圆层由不同光刻机分区域完成。缺口是把「套刻」从同机指标升格为跨机契约。它是 EUV 时代控制单位成本的核心手段之一。本课不做套刻计量学全貌。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV 光刻机的产能（约 160-200 wph）与折旧构成先进节点的成本大头，但许多层的图形只有局部复杂（cell 内），其余是稀疏大块。全层 EUV 是浪费。缺口：<strong>关键区域 EUV + 其余 DUV 的分区拼接</strong>——前提是两台机器写的图形在同一层内互相对准到几个纳米。这比层间套刻难：同一层的两个部分失配会直接图形断裂/短路。</p><p><span class="marginnote">术语翻译：mix-and-match = 分区混合光刻，同一层由 ≥2 台光刻机接力；BC（border/cut 区域）= 两机器负责区的交界；MAM overlay = 跨机器的场内套刻指标，通常比同机套刻紧 20–40%。</span></p><p><span class="marginnote">数字实例：某 3nm 层 EUV 覆盖率 40%（关键 cell 区）、DUV 覆盖 60%。EUV 产能翻倍需求降至 0.4 倍整层——按 180M 美元机价与 15 年折旧，单层光刻成本降约 35%；代价是 MAM overlay 指标从 2.5nm 收紧到 1.8nm 级。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>执行四要素：<strong>分区规划</strong>——关键/非关键区域的边界在设计阶段划定，边界落在图形简单处；<strong>基准对齐</strong>——DUV 机台以 EUV 已写图形的实测位置为基准做场内对准（先进对准方案用光栅/专用 mark）；<strong>匹配校正</strong>——两机的畸变地图互校（lens matching），把系统性错位按场域网格修正；<strong>计量闭环</strong>——边界区放密集套刻 mark，测得的 MAM overlay 喂回各机平台校正。顺序多变体：EUV-first（DUV 填空，最常用）与 DUV-first（EUV 打关键补丁，用于关键层小面积图形）。</p>',9)),(r(),n(s,null,{default:t(()=>[i(l,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E8%AE%BE%E8%AE%A1%E5%88%86%E5%8C%BA%3A%20%E5%85%B3%E9%94%AE%2F%E9%9D%9E%E5%85%B3%E9%94%AE%22%5D%20--%3E%20B%5B%22EUV%20%E5%86%99%E5%85%B3%E9%94%AE%E5%8C%BA%22%5D%0A%20%20B%20--%3E%20C%5B%22%E5%AE%9E%E6%B5%8B%20EUV%20%E5%9B%BE%E5%BD%A2%E4%BD%8D%E7%BD%AE%22%5D%0A%20%20C%20--%3E%20D%5B%22DUV%20%E4%BB%A5%E6%AD%A4%E4%B8%BA%E5%9F%BA%E5%87%86%E5%AF%B9%E5%87%86%22%5D%0A%20%20D%20--%3E%20E%5B%22%E7%95%B8%E5%8F%98%E5%9C%B0%E5%9B%BE%E4%BA%92%E6%A0%A1%20lens%20matching%22%5D%0A%20%20E%20--%3E%20F%5B%22%E8%BE%B9%E7%95%8C%20mark%20%E8%AE%A1%E9%87%8F%E9%97%AD%E7%8E%AF%22%5D%0A%20%20F%20--%3E%20G%5B%22MAM%20overlay%20%E8%BE%BE%E6%A0%87%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：像壁画接龙——大师（EUV）画面部（关键 cell），助手（DUV）补衣褶背景（大块简单图形）；助手动笔前先量好大师画好的五官坐标（基准对齐），两台「透视习惯」（畸变）不同的手要事先校准（lens matching），交界处一遍遍回看（计量闭环）。")],-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,[e("套刻误差的来源分解决定 MAM 的难度构成："),E("strong",null,"机器间失配"),e("（两台的镜头畸变、平台网格不同）是 MAM 特有项，靠 lens matching 把 EUV 的畸变地图「教」给 DUV 对准算法抵消；"),E("strong",null,"晶圆形变"),e("（工艺热预算导致的翘曲）两机各自补偿但基准不同步——先进方案的解法是共享同一套晶圆形变模型；"),E("strong",null,"对准标记质量"),e("——EUV-first 时 DUV 要看见 EUV 层的 mark，mark 在多层膜下的对比度是计量工程。收敛机制：计量-校正闭环让 MAM overlay 收敛到「两机共模误差 + 各自随机项的 RSS」——系统性项被模型吃掉后，剩下的就是光刻平台的本征稳定性。")],-1)),(r(),n(s,null,{default:t(()=>[i(l,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%7B%22MAM%20%E9%9A%BE%E5%9C%A8%E5%93%AA%3F%22%7D%20--%3E%20R%5B%22%E6%9C%BA%E5%99%A8%E9%97%B4%E7%95%B8%E5%8F%98%E5%A4%B1%E9%85%8D%22%5D%0A%20%20R%20--%3E%20S%5B%22lens%20matching%20%E6%95%99%E7%BB%99%E5%AF%B9%E6%96%B9%22%5D%0A%20%20T%7B%22%E6%99%B6%E5%9C%86%E4%BC%9A%E5%8F%98%E5%BD%A2%3F%22%7D%20--%3E%20U%5B%22%E5%85%B1%E4%BA%AB%E5%BD%A2%E5%8F%98%E6%A8%A1%E5%9E%8B%22%5D%0A%20%20V%7B%22%E7%9C%8B%E5%BE%97%E8%A7%81%E5%AF%B9%E6%96%B9%E7%9A%84%20mark%3F%22%7D%20--%3E%20W%5B%22EUV%20%E5%A4%9A%E5%B1%82%E8%86%9C%E4%B8%8B%20mark%20%E5%AF%B9%E6%AF%94%E5%BA%A6%22%5D%0A%20%20S%20--%3E%20X%5B%22%E7%B3%BB%E7%BB%9F%E6%80%A7%E9%A1%B9%E8%A2%AB%E6%A8%A1%E5%9E%8B%E5%90%83%E6%8E%89%22%5D%0A%20%20U%20--%3E%20X%0A%20%20W%20--%3E%20Y%5B%22%E5%89%A9%E9%9A%8F%E6%9C%BA%E9%A1%B9%20RSS%20%E2%86%92%20%E6%8C%87%E6%A0%87%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">常见误区：把 MAM overlay 当层间套刻处理——同层失配直接撕裂图形，指标更紧、闭环更密；另一误区是「分区越多越省」——每加一台机器加入接力，多一份失配源与产能协调成本，实际分区数通常 ≤2-3。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>MAM 的边界由「关键区域的可分性」决定：SRMA 阵列式规则图形天然易分区，随机逻辑的边界犬牙交错则收益骤降。EUV 单机产能提升（High-NA 与 faster stages）持续侵蚀 MAM 的成本论据——MAM 的份额是「EUV 产能 × 层数 × 设计可分性」的函数。High-NA 场域减半后，MAM 与 stitching 的组合（关键小区 High-NA + 大面积 low-NA）成为 imec 路线图上的活跃方案。与<a href="/litho/wafer-edge-exclusion">晶圆边缘排除区</a>的接续：分区规划时边缘低良率区优先派给 DUV——好的分区策略顺手把边缘损失也消化了。</p><p><span class="marginnote">直觉类比：MAM 像合资装修——贵的木工（EUV）只做客厅造型墙，刷漆铺砖（DUV）交给普通工人；两个工种各干各的不难，难的是「墙面的分界线处」瓷砖与木饰面严丝合缝——所以先量木工的实际尺寸，再让瓦工按此放线。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MAM = 同层分区跨机接力，省 EUV 产能、考跨机套刻。</li><li>三大机制项：lens matching 消畸变、共享形变模型、mark 对比度。</li><li>分区可分性决定收益；High-NA 时代 MAM×stitching 活跃。</li><li>出处：ASML MAM 方案资料；imec 混合光刻路线图；SPIE Overlay 计量会议文集。</li></ul>',6))])}const f=o(d,[["render",h]]);export{U as __pageData,f as default};
